export const getCapacityQuestionText = (type, id) => {
  let list = [];
  if (type === 'adaptive') list = adaptiveQuestions;
  if (type === 'absorptive') list = absorptiveQuestions;
  if (type === 'transformative') list = transformativeQuestions;
  
  const q = list.find(q => q.id === parseInt(id));
  return q ? q.text : `Question ${id}`;
};

export const getCapacityOptionLabel = (type, id, val) => {
  let list = [];
  if (type === 'adaptive') list = adaptiveQuestions;
  if (type === 'absorptive') list = absorptiveQuestions;
  if (type === 'transformative') list = transformativeQuestions;
  
  const q = list.find(q => q.id === parseInt(id));
  if (!q) return val;
  const opt = q.options.find(o => o.value === parseInt(val));
  return opt ? opt.label : val;
};
